def common_elements(a, b):
    set_b = set(b)
    # Using a set comprehension to find common elements and then sorting
    # We also need to handle the 'x not in out' logic which implies uniqueness in output
    # The original code: if x in b and x not in out: out.append(x)
    # This means for each x in a, if it's in b, it's added to out if it's not already there.
    # So the result is the set of elements in both a and b, sorted.
    common = set(a).intersection(set_b)
    return sorted(list(common))


